@page "/dashboard"
@rendermode InteractiveServer
@inject Services.WarehouseStateService WarehouseState
@inject Services.InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Current Site</h5>
                <p class="card-text fs-4">@GetWarehouseName()</p>
            </div>
        </div>
    </div>
    <div class="col-md-4">
        <div class="card @(AlertService.CurrentLowStockCount > 5 ? "border-danger" : "border-warning")">
            <div class="card-body text-center">
                <h5 class="card-title">Low Stock Alerts</h5>
                <p class="card-text fs-1 fw-bold @(AlertService.CurrentLowStockCount > 5 ? "text-danger" : "text-warning")">
                    @AlertService.CurrentLowStockCount
                </p>
                <small class="text-muted">Items below minimum level</small>
            </div>
        </div>
    </div>
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Polling Status</h5>
                <p class="card-text">
                    <span class="badge bg-success">● Active</span>
                    <br />
                    <small class="text-muted">Refreshes every 10s</small>
                </p>
            </div>
        </div>
    </div>
</div>

<div class="mt-4">
    <p class="text-muted">
        Last updated: @_lastUpdate.ToString("HH:mm:ss")
    </p>
</div>

@code {
    private DateTime _lastUpdate = DateTime.Now;

    protected override void OnInitialized()
    {
        // Subscribe to polling — starts the timer if this is the first subscriber
        AlertService.Subscribe();

        // Listen for data changes to re-render
        AlertService.OnAlertDataChanged += HandleAlertDataChanged;
        WarehouseState.OnWarehouseChanged += HandleWarehouseChanged;
    }

    private async Task HandleAlertDataChanged()
    {
        _lastUpdate = DateTime.Now;
        await InvokeAsync(StateHasChanged);
    }

    private async Task HandleWarehouseChanged()
    {
        await InvokeAsync(StateHasChanged);
    }

    private string GetWarehouseName()
    {
        var wh = Services.WarehouseStateService.AvailableWarehouses
            .FirstOrDefault(w => w.Id == WarehouseState.CurrentWarehouseId);
        return wh != default ? wh.Name : WarehouseState.CurrentWarehouseId;
    }

    public void Dispose()
    {
        AlertService.OnAlertDataChanged -= HandleAlertDataChanged;
        WarehouseState.OnWarehouseChanged -= HandleWarehouseChanged;
        AlertService.Unsubscribe();
    }
}

